#pragma once
#include "../../FreeInkUICore.h"
namespace freeink { namespace ui {
enum class SheetEdge : uint8_t { Top, Bottom };
struct SheetProps { SheetEdge anchor=SheetEdge::Top; Paint background=Paint::solid(Color::White); Paint rule=Paint::solid(Color::Black); int16_t ruleWidth=2; Paint grabber=Paint::solid(Color::Black); int16_t grabberWidth=72; int16_t grabberHeight=5; int16_t grabberInset=16; int16_t grabberMargin=8; uint8_t radius=RADIUS_INHERIT; ActionId dismissAction=NO_ACTION; };
inline Rect sheetContentRect(Rect rect,const SheetProps& props){ const int16_t band=static_cast<int16_t>(props.grabberMargin+props.grabberHeight+props.grabberInset); return props.anchor==SheetEdge::Top?rect.inset(Insets{0,0,band,0}):rect.inset(Insets{band,0,0,0}); }
template <size_t MaxInteractions> void sheet(Frame<MaxInteractions>& frame,Rect rect,const SheetProps& props){ const bool fromTop=props.anchor==SheetEdge::Top; frame.target().fill(rect,props.background,resolveRadius(props.radius,0),fromTop?CornersBottom:CornersTop); if(props.ruleWidth>0){ const int16_t ruleY=fromTop?static_cast<int16_t>(rect.bottom()-props.ruleWidth):rect.y; frame.target().fill(Rect{rect.x,ruleY,rect.width,props.ruleWidth},props.rule);} if(props.grabberWidth>0&&props.grabberHeight>0){ const int16_t grabberY=fromTop?static_cast<int16_t>(rect.bottom()-props.grabberInset-props.grabberHeight):static_cast<int16_t>(rect.y+props.grabberInset); const Rect grabber{static_cast<int16_t>(rect.x+(rect.width-props.grabberWidth)/2),grabberY,props.grabberWidth,props.grabberHeight}; frame.target().fill(grabber,props.grabber,static_cast<uint8_t>(props.grabberHeight/2)); } if(props.dismissAction!=NO_ACTION){ const Rect screen=frame.safeRect(); const Rect outside=fromTop?Rect{screen.x,rect.bottom(),screen.width,static_cast<int16_t>(screen.bottom()-rect.bottom())}:Rect{screen.x,screen.y,screen.width,static_cast<int16_t>(rect.y-screen.y)}; if(!outside.empty())frame.hit(outside,props.dismissAction,0,InputTouch);} }
} }
